// scan.Mapper[*T] without reflection: maps columns to fields by index.
func recurringExpenseScanMapper(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*RecurringExpense, error)) {
	// resolve the column positions once per query, not per row
	type target struct {
		idx int
		dst func(o *RecurringExpense) any
	}
	targets := make([]target, 0, 16)
	for i, col := range cols {
		switch col {
		case "id":
			targets = append(targets, target{i, func(o *RecurringExpense) any { return &o.ID }})
		case "household_id":
			targets = append(targets, target{i, func(o *RecurringExpense) any { return &o.HouseholdID }})
		case "name":
			targets = append(targets, target{i, func(o *RecurringExpense) any { return &o.Name }})
		case "merchant":
			targets = append(targets, target{i, func(o *RecurringExpense) any { return &o.Merchant }})
		case "amount_yen":
			targets = append(targets, target{i, func(o *RecurringExpense) any { return &o.AmountYen }})
		case "currency":
			targets = append(targets, target{i, func(o *RecurringExpense) any { return &o.Currency }})
		case "category_id":
			targets = append(targets, target{i, func(o *RecurringExpense) any { return &o.CategoryID }})
		case "payment_account_id":
			targets = append(targets, target{i, func(o *RecurringExpense) any { return &o.PaymentAccountID }})
		case "cadence":
			targets = append(targets, target{i, func(o *RecurringExpense) any { return &o.Cadence }})
		case "starts_on":
			targets = append(targets, target{i, func(o *RecurringExpense) any { return &o.StartsOn }})
		case "next_due_on":
			targets = append(targets, target{i, func(o *RecurringExpense) any { return &o.NextDueOn }})
		case "ends_on":
			targets = append(targets, target{i, func(o *RecurringExpense) any { return &o.EndsOn }})
		case "archived":
			targets = append(targets, target{i, func(o *RecurringExpense) any { return &o.Archived }})
		case "revision":
			targets = append(targets, target{i, func(o *RecurringExpense) any { return &o.Revision }})
		case "created_at":
			targets = append(targets, target{i, func(o *RecurringExpense) any { return &o.CreatedAt }})
		case "updated_at":
			targets = append(targets, target{i, func(o *RecurringExpense) any { return &o.UpdatedAt }})
		}
	}

	return func(row *scan.Row) (any, error) {
			o := new(RecurringExpense)
			for _, t := range targets {
				row.ScheduleScanByIndex(t.idx, t.dst(o))
			}
			return o, nil
		}, func(v any) (*RecurringExpense, error) {
			return v.(*RecurringExpense), nil
		}
}

