// LoadCategory loads the recurringExpense's Category into the .R struct
func (os RecurringExpenseSlice) LoadCategory(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	categories, err := os.Category(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Category = nil
		o.R.Loaded.Category = true
	}
	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range categories {

			if !(o.HouseholdID == rel.HouseholdID) {
				continue
			}
			if !o.CategoryID.Valid {
				continue
			}

			if !(o.CategoryID.Valid && o.CategoryID.V == rel.ID) {
				continue
			}

			rel.R.RecurringExpenses = append(rel.R.RecurringExpenses, o)

			o.R.Category = rel
			break
		}
	}

	return nil
}

